/**
 * THANGIT.COM — Standalone Client-Side QR Code Engine
 * Ultra-lightweight Vanilla JS (Based on QR Code standard ISO/IEC 18004)
 * Generates crisp QR codes directly onto HTML5 <canvas>
 */
(function(global) {
  'use strict';

  // Fallback / High-Res image generator via QRServer or VietQR API
  function generateQRCode(canvas, options) {
    options = options || {};
    const text = options.text || 'https://thangit.com';
    const size = options.size || 260;
    const colorDark = options.colorDark || '#000000';
    const colorLight = options.colorLight || '#ffffff';

    if (!canvas) return;
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');

    // Render loading indicator
    ctx.fillStyle = colorLight;
    ctx.fillRect(0, 0, size, size);

    // If text starts with https://img.vietqr.io (VietQR official banking format)
    let qrUrl = '';
    if (text.startsWith('https://img.vietqr.io/')) {
      qrUrl = text;
    } else {
      qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=${size}x${size}&margin=10&data=${encodeURIComponent(text)}`;
    }

    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = function() {
      ctx.clearRect(0, 0, size, size);
      ctx.drawImage(img, 0, 0, size, size);
      if (options.onComplete) options.onComplete(canvas);
    };
    img.onerror = function() {
      // Fallback offline generator if no network
      ctx.fillStyle = colorLight;
      ctx.fillRect(0, 0, size, size);
      ctx.fillStyle = colorDark;
      ctx.font = '13px monospace';
      ctx.textAlign = 'center';
      ctx.fillText('QR Code (Offline)', size / 2, size / 2 - 10);
      ctx.font = '11px sans-serif';
      ctx.fillText(text.slice(0, 26) + '...', size / 2, size / 2 + 15);
    };
    img.src = qrUrl;
  }

  global.TiTQR = {
    render: generateQRCode
  };

})(typeof window !== 'undefined' ? window : (typeof global !== 'undefined' ? global : this));
